# Archive bridge: translate identifiers between systems via mapping tables, then hop.
mappings = {('alpha','beta'): {'A-101': 'B-202'}, ('beta','gamma'): {'B-202': 'G-303'}}
hops = ['beta','gamma']
def translate(ident, src, dst):
    key = (src, dst)
    if key not in mappings: return None
    return mappings[key].get(ident)
ident, src = "A-101", "alpha"
print(f"Start: {ident} in {src}")
for dst in hops:
    nxt = translate(ident, src, dst)
    if nxt is None:
        print(f"  no mapping {src} -> {dst}; stop"); break
    print(f"  {src} -> {dst}: {ident} becomes {nxt}")
    ident, src = nxt, dst

